        Root cause:
        The bug was caused by the incorrect conditional logic in the `compile_call_cc` function, where the `emit_frame` function was being called for tail calls instead of being skipped. This led to improper handling of function calls, potentially resulting in incorrect program behavior or stack management issues.

        Commit message:
        Bugfix: fix bug introduced in commit 4779b1b  

        Patch:

 static rsexp compile_call_cc (RState* state, rsexp expr, rsexp next)
 {
     rsexp code;

     if (!validate_call_cc (state, expr))
         return R_FAILURE;

     r_gc_scope_open (state);

     ensure_or_goto (code = emit_apply (state), exit);
     ensure_or_goto (code = compile (state, r_cadr (expr), code), exit);
     ensure_or_goto (code = emit_arg (state, code), exit);
     ensure_or_goto (code = emit_capture_cc (state, code), exit);

-    if (tail_p (state, next))
-        ensure_or_goto (code = emit_frame (state, next, code), exit);
+    if (!tail_p (state, next))
+        code = emit_frame (state, next, code);

 exit:
     r_gc_scope_close_and_protect (state, code);

     return code;
 }



